462: function updateAndDrawRipples() {
463:   for (let i = ripples.length - 1; i >= 0; i--) {
464:     const r = ripples[i];
465:     r.r += 0.45;
466:     r.alpha *= 0.965;
467:     if (r.alpha < 0.02 || r.r >= r.maxR) {
468:       ripples.splice(i, 1);
469:       continue;
470:     }
471:     ctx.save();
472:     ctx.beginPath();
473:     ctx.ellipse(r.x, r.y, r.r, r.r * 0.32, 0, 0, Math.PI * 2);
474:     ctx.strokeStyle = `rgba(255, 252, 230, ${r.alpha})`;
475:     ctx.lineWidth = 1.3;
476:     ctx.stroke();
477:     ctx.restore();
478:   }
479: }
